/* MIT. Stable near/far traversal; a fresh nearest selection is always available. */
static int target_visible47(const Combat*g,int i,float yaw,float tilt,float zoom){if(!combat_valid_target((Combat*)g,i))return 0;const CombatMob*m=&g->mobs[i];float dx=m->x-g->x,dy=m->y-g->y;float sx=320+zoom*(cosf(yaw)*dx+sinf(yaw)*dy),sy=245+zoom*cosf(tilt)*(sinf(yaw)*dx-cosf(yaw)*dy);return sx>24&&sx<616&&sy>105&&sy<410;}
static int target_distance_before47(const Combat*g,int a,int b){const CombatMob*x=&g->mobs[a],*y=&g->mobs[b];float dx=(x->x-g->x)*(x->x-g->x)+(x->y-g->y)*(x->y-g->y),dy=(y->x-g->x)*(y->x-g->x)+(y->y-g->y)*(y->y-g->y);if(fabsf(dx-dy)>.01f)return dx<dy;if(!!x->aggro!=!!y->aggro)return !!x->aggro;if(x->hp!=y->hp)return x->hp<y->hp;return a<b;}
static void target_select47(Combat*g,int direction,float yaw,float tilt,float zoom){int list[MOB_COUNT],n=0,current=-1;g->approachSkill53=0;for(int i=0;i<MOB_COUNT;i++)if(target_visible47(g,i,yaw,tilt,zoom)){int at=n;while(at&&target_distance_before47(g,i,list[at-1])){list[at]=list[at-1];at--;}list[at]=i;n++;}for(int i=0;i<n;i++)if(list[i]==g->target)current=i;if(!n){g->target=-1;return;}if(!direction||current<0)current=0;else{current+=direction>0?1:-1;if(current<0)current=0;if(current>=n)current=n-1;}g->target=list[current];}

/* Gameplay buttons: R3 nearest, X inward, Y outward. 2 means no request. */
static int target_button47a(unsigned pressed){return pressed&64?0:pressed&8?-1:pressed&16?1:2;}
